INSERT INTO curriculum_topics (level, subject_id, component_id, unit_number, theme, week_number, topic_title, topic_description, savoir_etre, has_content) VALUES
  ('cm1', 'maths', 'nombres-calculs', 1, 'La nature', 1, 'Ensembles et grands nombres', 'Utiliser le diagramme de Venn pour représenter des ensembles; Composer, décomposer les grands nombres entiers en utilisant des regroupements par millier (nombres jusqu''au million); Ajouter ou retrancher 10 à un nombre entier.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 1, 'La nature', 2, 'Valeur des chiffres et opérations', 'Déterminer la valeur de chaque chiffre dans un nombre; Calculer la somme et la différence des nombres entiers par un calcul en ligne ou posé; Ajouter ou retrancher 8, 9 à un nombre.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 1, 'La nature', 3, 'Nombres de 9 chiffres', 'Lire, écrire en chiffres et en lettres les nombres de 9 chiffres; Comparer, ranger les nombres entiers de 9 chiffres; Ajouter ou retrancher 18, 19 à un nombre.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 2, 'Le village, la ville', 1, 'Ensembles et grands nombres', 'Représenter l''union et l''intersection des ensembles dans le diagramme de Venn; encadrer et arrondir des grands nombres entiers de 9 chiffres, les repérer et les placer sur une droite graduée adaptée.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 2, 'Le village, la ville', 2, 'Produit et preuve par 9', 'Calculer le produit de deux entiers et faire une preuve par 9 pour vérifier la justesse du résultat; vérifier la vraisemblance d''un résultat en estimant son ordre de grandeur (pour l''addition, soustraction, multiplication).', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 2, 'Le village, la ville', 3, 'Tables de multiplication', 'Construire les tables de multiplication de 1 à 10.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 3, 'L''école', 1, 'Notion de nombre décimal', 'Utiliser l''inclusion et l''union dans la description et l''interprétation des situations de la vie courante; expliquer la notion de nombre décimal; lire et écrire un nombre décimal en lettres et en chiffres.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 3, 'L''école', 2, 'Comparer et ranger les décimaux', 'Repérer et placer un nombre décimal sur une demi-droite graduée; comparer et ranger des nombres décimaux; ajouter des compléments aux nombres décimaux pour obtenir l''unité (ex : 0,7+…=1).', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 3, 'L''école', 3, 'Multiplier et calculer les décimaux', 'Multiplier un nombre par 0,1 ; 0,5 ; 0,01 ; 0,001; calculer la somme et la différence des nombres décimaux par un calcul en ligne ou posé; calculer le produit d''un décimal par un entier ou d''un entier par un décimal par un calcul posé.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 4, 'Les métiers', 1, 'Fractions et encadrement', 'Encadrer des nombres décimaux par deux nombres entiers consécutifs; utiliser les termes demi, tiers, quart, dixième, centième pour nommer une fraction; écrire et lire en chiffres et en lettres les fractions; encadrer une fraction par deux nombres entiers consécutifs.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 4, 'Les métiers', 2, 'Division et divisibilité', 'Diviser des nombres entiers; diviser un nombre entier par un nombre décimal; facteur de divisibilité par 2, 3, 5.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 4, 'Les métiers', 3, 'Multiplier et diviser par 10, 100, 1000', 'Multiplier un nombre entier par 10, 100, 1000; diviser un nombre entier par 10, 100, 1000.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 5, 'Les voyages', 1, 'Fractions : réduire, comparer', 'Réduire les fractions au même dénominateur; simplifier les fractions; comparer les fractions à l''unité; établir la relation d''ordre avec les fractions de même dénominateur ou de même numérateur.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 5, 'Les voyages', 2, 'Opérations sur les fractions', 'Calculer la somme ou la différence de deux fractions ayant le même dénominateur; multiplier un nombre par une fraction; multiplier une fraction par un nombre entier; multiplier deux fractions.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 5, 'Les voyages', 3, 'Calcul mental', 'Calcul mental : multiplier un nombre par 5, 50, 500; multiplier un nombre par 0,5; diviser un nombre par 5, 50, 500.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 6, 'La santé', 1, 'Les nombres complexes', 'Les nombres complexes : Définir la notion de nombre complexe ; Écrire un nombre complexe sous forme de nombre entier ; Écrire un nombre entier sous forme de nombre complexe.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 6, 'La santé', 2, 'Additionner et soustraire', 'Calculs : Additionner les nombres complexes ; Soustraire les nombres complexes.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 6, 'La santé', 3, 'Multiplier et diviser', 'Calculs : Multiplier un nombre complexe par un nombre entier ; Diviser un nombre complexe par un nombre entier.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 7, 'Sports et loisirs', 1, 'Les mouvements uniformes', 'Les mouvements uniformes : Définir les notions d''heure de départ et d''heure d''arrivée; Définir la notion de distance parcourue; Définir la notion de temps mis dans un trajet.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 7, 'Sports et loisirs', 2, 'Calculs de trajet', 'Calculs : Calculer l''heure de départ et l''heure d''arrivée; Calculer la distance parcourue.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 7, 'Sports et loisirs', 3, 'Calculs de durée', 'Calculs : Calculer le temps mis; Calculer la durée d''un trajet.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 8, 'Dans l''espace', 1, 'Les opérations commerciales', 'Les opérations commerciales : Définir les termes : gain, économie, dépense, perte, réduction, augmentation, remise, solde.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 8, 'Dans l''espace', 2, 'Calculer les prix', 'Calculs : Calculer le prix de vente ; Calculer le prix de revient ; Calculer le prix d''achat.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'nombres-calculs', 8, 'Dans l''espace', 3, 'Calculer perte et bénéfice', 'Calculs : Calculer la perte ; Calculer le bénéfice, le gain.', 'Avoir un raisonnement cohérent et logique', false),
  ('cm1', 'maths', 'mesures-grandeurs', 1, 'La nature', 1, 'Convertir les longueurs', 'Convertir les unités de mesure de longueur en unités plus grandes que le mètre.', 'Être précis et avoir le sens de la mesure et du jugement', false),
  ('cm1', 'maths', 'mesures-grandeurs', 1, 'La nature', 2, 'Périmètre par formule', 'Déterminer la mesure des périmètres en utilisant une formule (pour le carré, le rectangle).', 'Être précis et avoir le sens de la mesure et du jugement', false),
  ('cm1', 'maths', 'mesures-grandeurs', 1, 'La nature', 3, 'Calculer des périmètres', 'Calculer des périmètres en mobilisant les formules pour le carré, le rectangle et le cercle.', 'Être précis et avoir le sens de la mesure et du jugement', false),
  ('cm1', 'maths', 'mesures-grandeurs', 2, 'Le village, la ville', 1, 'Unités de capacité et volume', 'Convertir les unités de mesure de capacités en unités plus grandes que le litre; connaître les unités usuelles de volume (cm3, dm3, m3), relations entre les unités.', 'Être précis et avoir le sens de la mesure et du jugement', false),
  ('cm1', 'maths', 'mesures-grandeurs', 2, 'Le village, la ville', 2, 'Volume du pavé et du cube', 'Déterminer le volume d''un pavé droit ou d''un cube en se rapportant à un dénombrement d''unités.', 'Être précis et avoir le sens de la mesure et du jugement', false),
