  ('cm1', 'langues', 'langue-nationale', 6, 'La santé', 1, 'La santé : médicaments traditionnels', 'La santé : identifier les médicaments traditionnels pour soigner les maladies courantes.', 'Être enraciné dans sa culture', false),
  ('cm1', 'langues', 'langue-nationale', 6, 'La santé', 2, 'Les maladies', 'Les maladies : nommer les maladies; décrire les symptômes des maladies fréquentes (paludisme, rhume, mal de ventre, etc.).', 'Être enraciné dans sa culture', false),
  ('cm1', 'langues', 'langue-nationale', 6, 'La santé', 3, 'Industrie du médicament', 'L''industrie du médicament : expliquer comment on soigne traditionnellement quelques maladies dans son village.', 'Être enraciné dans sa culture', false),
  ('cm1', 'langues', 'langue-nationale', 7, 'Sports et loisirs', 1, 'Les sports de compétition', 'Décrire les sports de compétition pratiqués dans son village.', 'Être enraciné dans sa culture', false),
  ('cm1', 'langues', 'langue-nationale', 7, 'Sports et loisirs', 2, 'Les loisirs pour jeunes', 'Nommer des jeux ou des sports traditionnellement pratiqués dans sa région et expliquer les règles.', 'Être enraciné dans sa culture', false),
